<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Neon Neuron Growth</title>
<!-- dat.gui is the only external library -->
<script src="https://cdn.jsdelivr.net/npm/dat.gui@0.7.9/build/dat.gui.min.js"></script>
<style>
  /* ---------- Base page: dark backdrop, centered canvas ---------- */
  html, body {
    margin: 0;
    padding: 0;
    height: 100%;
    background: #05070f;
    overflow: hidden;
    font-family: 'Segoe UI', Consolas, monospace;
  }
  body {
    display: flex;
    align-items: center;
    justify-content: center;
  }
  #stage {
    position: relative;
    width: 800px;
    height: 800px;
  }
  canvas {
    display: block;
    width: 800px;
    height: 800px;
    border: 1px solid rgba(0, 229, 255, 0.25);
    box-shadow: 0 0 40px rgba(0, 229, 255, 0.15), inset 0 0 60px rgba(16, 26, 58, 0.6);
    background: #05070f;
  }
  /* ---------- dat.gui restyle to match neon accent ---------- */
  .dg.ac { z-index: 10 !important; }
  .dg .c .slider-fg { background: #ffd400 !important; }
  .dg .property-name { color: #9adfe8 !important; }
  .dg .c input[type=text] { color: #ffd400 !important; }
  .dg li.title { color: #00e5ff !important; letter-spacing: 1px; }
  .dg .cr.function .property-name { color: #d6ff00 !important; }
</style>
</head>
<body>
<div id="stage">
  <canvas id="cv" width="800" height="800"></canvas>
</div>

<script>
'use strict';

/* =========================================================
   SETUP
   ========================================================= */
const W = 800, H = 800;
const cv = document.getElementById('cv');
const ctx = cv.getContext('2d');

// Tunable parameters (bound to dat.gui)
const params = {
  // Growth
  neuronCount: 4,          // 3..6 seed neurons
  growthSpeed: 1.6,        // pixels per step per growing tip
  maxDepth: 6,             // recursion depth limit
  splitChance: 0.035,      // chance per step to spawn a side branch
  curvature: 0.55,         // random angular drift per step
  maxBranchLen: 170,       // max length of a single branch segment chain
  // Synapses
  synapseDist: 26,         // tip proximity threshold for synapse formation
  synapseGlow: 18,         // shadowBlur for synapse glow
  // Pulses
  pulseSpeed: 3.2,         // travel speed of sparks along connections
  pulseFrequency: 0.9,     // new pulses spawned per second (approx)
  pulseBrightness: 1.0,    // brightness multiplier for sparks
  // Visuals
  bgColor: '#05070f',
  glowColor: '#101a3a',
  branchColor: '#00e5ff',
  accentColor: '#d6ff00',
  synapseColor: '#ff2bd6',
  pulseColor: '#fff36a',
  scanlines: true,
  // Actions
  regenerate: () => regenerate(),
  clear: () => clearCanvas(),
  togglePause: () => { paused = !paused; }
};

// Network state — lightweight arrays/objects only
let tips = [];        // active growing tips
let segments = [];    // {a:{x,y}, b:{x,y}, w, depth, accent}
let neurons = [];     // seed neuron bodies {x,y,r}
let synapses = [];    // {a:{x,y}, b:{x,y}, id1, id2, phase}
let pulses = [];      // {syn, t} travelling sparks
let tipSeq = 0;       // unique id per tip lineage for duplicate prevention
let paused = false;
let growthDone = false;
let scanOffset = 0;

const MAX_TIPS = 90;        // hard cap on concurrent growth
const MAX_SEGMENTS = 2600;  // hard cap on drawn segments
const MAX_SYNAPSES = 140;

/* =========================================================
   NEURON GROWTH
   ========================================================= */
function makeTip(x, y, angle, depth, width, parentId) {
  return {
    x, y, angle, depth,
    w: width * (0.85 + Math.random() * 0.3),  // slight thickness variation
    len: 0,
    id: parentId !== undefined ? parentId : (tipSeq++),
    curve: (Math.random() - 0.5) * 0.6        // per-tip smooth drift bias
  };
}

function regenerate() {
  tips = []; segments = []; neurons = []; synapses = []; pulses = [];
  tipSeq = 0; growthDone = false;
  const n = Math.round(params.neuronCount);
  for (let i = 0; i < n; i++) {
    // Seed neurons clustered near center
    const x = W / 2 + (Math.random() - 0.5) * 180;
    const y = H / 2 + (Math.random() - 0.5) * 180;
    neurons.push({ x, y, r: 5 + Math.random() * 4 });
    // A few primary axons per neuron
    const k = 2 + (Math.random() * 2 | 0);
    for (let j = 0; j < k; j++) {
      tips.push(makeTip(x, y, Math.random() * Math.PI * 2, 0, 2.2));
    }
  }
  paintBackground();
}

function stepGrowth() {
  if (growthDone) return;
  const next = [];
  for (const t of tips) {
    // Organic curve: per-tip bias + random jitter
    t.angle += t.curve * 0.12 + (Math.random() - 0.5) * params.curvature * 0.25;
    const nx = t.x + Math.cos(t.angle) * params.growthSpeed;
    const ny = t.y + Math.sin(t.angle) * params.growthSpeed;

    // Keep growth inside canvas; steer back instead of dying
    let angle2 = t.angle;
    if (nx < 20 || nx > W - 20 || ny < 20 || ny > H - 20) {
      angle2 = Math.atan2(H / 2 - t.y, W / 2 - t.x) + (Math.random() - 0.5);
    }
    const bx = t.x + Math.cos(angle2) * params.growthSpeed;
    const by = t.y + Math.sin(angle2) * params.growthSpeed;

    segments.push({
      a: { x: t.x, y: t.y }, b: { x: bx, y: by },
      w: t.w, depth: t.depth,
      accent: t.depth >= 2 && Math.random() < 0.25
    });

    t.x = bx; t.y = by; t.angle = angle2;
    t.len += params.growthSpeed;

    // Occasional side branch (smaller, thinner)
    if (t.depth < params.maxDepth && tips.length + next.length < MAX_TIPS &&
        segments.length < MAX_SEGMENTS && Math.random() < params.splitChance) {
      const side = (Math.random() < 0.5 ? 1 : -1) * (0.6 + Math.random() * 0.8);
      next.push(makeTip(t.x, t.y, t.angle + side, t.depth + 1, t.w * 0.7, t.id));
    }

    // Tip occasionally splits into two deeper branches
    if (t.depth < params.maxDepth && tips.length + next.length < MAX_TIPS &&
        segments.length < MAX_SEGMENTS && Math.random() < params.splitChance * 0.6) {
      t.depth++;
      next.push(makeTip(t.x, t.y, t.angle + (Math.random() < 0.5 ? 1 : -1) *
        (0.5 + Math.random() * 0.7), t.depth, t.w * 0.75, t.id));
    }

    // Retire tip when branch reaches max length
    if (t.len < params.maxBranchLen) next.push(t);
  }
  tips = next;
  if (tips.length === 0 || segments.length >= MAX_SEGMENTS) growthDone = true;
  detectSynapses();
}

/* =========================================================
   SYNAPSE DETECTION
   ========================================================= */
const usedPairs = new Set();  // prevents duplicate synapses between same tips

function detectSynapses() {
  if (synapses.length >= MAX_SYNAPSES || tips.length < 2) return;
  const d2 = params.synapseDist * params.synapseDist;
  for (let i = 0; i < tips.length; i++) {
    for (let j = i + 1; j < tips.length; j++) {
      const a = tips[i], b = tips[j];
      if (a.id === b.id) continue;                 // same lineage
      const key = a.id < b.id ? a.id + '_' + b.id : b.id + '_' + a.id;
      if (usedPairs.has(key)) continue;            // already connected
      const dx = a.x - b.x, dy = a.y - b.y;
      if (dx * dx + dy * dy < d2) {
        usedPairs.add(key);
        synapses.push({ a: { x: a.x, y: a.y }, b: { x: b.x, y: b.y },
                        phase: Math.random() * Math.PI * 2 });
      }
    }
  }
}

/* =========================================================
   PULSE ANIMATION
   ========================================================= */
let pulseTimer = 0;

function spawnPulse() {
  if (!synapses.length) return;
  const s = synapses[Math.random() * synapses.length | 0];
  pulses.push({ syn: s, t: 0, dir: Math.random() < 0.5 ? 1 : -1 });
}

function stepPulses(dt) {
  // Spawn new pulses at requested frequency
  pulseTimer += dt * params.pulseFrequency;
  while (pulseTimer >= 1) { pulseTimer -= 1; spawnPulse(); }

  // Advance sparks; remove finished ones
  for (let i = pulses.length - 1; i >= 0; i--) {
    pulses[i].t += dt * params.pulseSpeed * 0.35;
    if (pulses[i].t >= 1) pulses.splice(i, 1);
  }
}

/* =========================================================
   RENDERING
   ========================================================= */
function paintBackground() {
  ctx.fillStyle = params.bgColor;
  ctx.fillRect(0, 0, W, H);
  // Radial background glow at center
  const g = ctx.createRadialGradient(W / 2, H / 2, 40, W / 2, H / 2, 520);
  g.addColorStop(0, params.glowColor);
  g.addColorStop(1, 'rgba(5,7,15,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  // Faint grid
  ctx.strokeStyle = 'rgba(0, 229, 255, 0.08)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let x = 0; x <= W; x += 40) { ctx.moveTo(x, 0); ctx.lineTo(x, H); }
  for (let y = 0; y <= H; y += 40) { ctx.moveTo(0, y); ctx.lineTo(W, y); }
  ctx.stroke();
}

function drawScene(time) {
  paintBackground();

  // ----- Branches (thin glowing neon, quadratic smoothing) -----
  ctx.lineCap = 'round';
  for (const s of segments) {
    ctx.save();
    ctx.strokeStyle = s.accent ? params.accentColor : params.branchColor;
    ctx.lineWidth = s.w;
    ctx.shadowColor = ctx.strokeStyle;
    ctx.shadowBlur = 6;
    ctx.globalAlpha = 0.85;
    const mx = (s.a.x + s.b.x) / 2 + (s.b.y - s.a.y) * 0.12;
    const my = (s.a.y + s.b.y) / 2 + (s.a.x - s.b.x) * 0.12;
    ctx.beginPath();
    ctx.moveTo(s.a.x, s.a.y);
    ctx.quadraticCurveTo(mx, my, s.b.x, s.b.y);
    ctx.stroke();
    ctx.restore();
  }

  // ----- Seed neuron bodies -----
  for (const n of neurons) {
    ctx.save();
    ctx.fillStyle = params.branchColor;
    ctx.shadowColor = params.branchColor;
    ctx.shadowBlur = 22;
    ctx.beginPath();
    ctx.arc(n.x, n.y, n.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // ----- Synapses (brighter glow, soft pulse over time) -----
  for (const s of synapses) {
    const glow = 0.6 + 0.4 * Math.sin(time * 0.003 + s.phase);
    ctx.save();
    ctx.strokeStyle = params.synapseColor;
    ctx.shadowColor = params.synapseColor;
    ctx.shadowBlur = params.synapseGlow * glow;
    ctx.lineWidth = 1.4;
    ctx.globalAlpha = 0.55 + 0.35 * glow;
    ctx.beginPath();
    ctx.moveTo(s.a.x, s.a.y);
    ctx.lineTo(s.b.x, s.b.y);
    ctx.stroke();
    // Node dots
    ctx.fillStyle = params.synapseColor;
    ctx.beginPath(); ctx.arc(s.a.x, s.a.y, 2.2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(s.b.x, s.b.y, 2.2, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }

  // ----- Pulses (electric sparks interpolated along synapses) -----
  for (const p of pulses) {
    const s = p.syn;
    const t = p.dir === 1 ? p.t : 1 - p.t;
    // Smooth interpolation with slight arc
    const x = s.a.x + (s.b.x - s.a.x) * t;
    const y = s.a.y + (s.b.y - s.a.y) * t;
    const arc = Math.sin(t * Math.PI) * 6;
    const nx = -(s.b.y - s.a.y), ny = (s.b.x - s.a.x);
    const nl = Math.hypot(nx, ny) || 1;
    const sx = x + (nx / nl) * arc, sy = y + (ny / nl) * arc;
    ctx.save();
    ctx.fillStyle = params.pulseColor;
    ctx.shadowColor = params.pulseColor;
    ctx.shadowBlur = 16 * params.pulseBrightness;
    ctx.globalAlpha = Math.min(1, params.pulseBrightness);
    ctx.beginPath(); ctx.arc(sx, sy, 3, 0, Math.PI * 2); ctx.fill();
    // Tiny jagged tail for the "electric" feel
    ctx.strokeStyle = params.pulseColor;
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.5 * params.pulseBrightness;
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.lineTo(sx + (Math.random() - 0.5) * 10, sy + (Math.random() - 0.5) * 10);
    ctx.stroke();
    ctx.restore();
  }

  // ----- Vignette -----
  const v = ctx.createRadialGradient(W / 2, H / 2, 280, W / 2, H / 2, 580);
  v.addColorStop(0, 'rgba(0,0,0,0)');
  v.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, W, H);

  // ----- Scanlines (subtle, animated) -----
  if (params.scanlines) {
    ctx.save();
    ctx.fillStyle = 'rgba(0, 229, 255, 0.08)';
    scanOffset = (scanOffset + 0.4) % 4;
    for (let y = scanOffset; y < H; y += 4) ctx.fillRect(0, y, W, 1);
    ctx.restore();
  }
}

function clearCanvas() {
  tips = []; segments = []; neurons = []; synapses = []; pulses = [];
  usedPairs.clear();
  growthDone = true;   // stay cleared until regenerate
  paintBackground();
}

/* =========================================================
   GUI SETUP (dat.gui)
   ========================================================= */
function buildGUI() {
  const gui = new dat.GUI({ width: 280 });

  const fGrowth = gui.addFolder('Growth');
  fGrowth.add(params, 'neuronCount', 3, 6, 1);
  fGrowth.add(params, 'growthSpeed', 0.4, 5, 0.1);
  fGrowth.add(params, 'maxDepth', 1, 10, 1);
  fGrowth.add(params, 'splitChance', 0, 0.15, 0.005);
  fGrowth.add(params, 'curvature', 0, 1.5, 0.05);
  fGrowth.add(params, 'maxBranchLen', 40, 400, 5);
  fGrowth.open();

  const fSyn = gui.addFolder('Synapses');
  fSyn.add(params, 'synapseDist', 5, 80, 1);
  fSyn.add(params, 'synapseGlow', 0, 40, 1);

  const fPulse = gui.addFolder('Pulses');
  fPulse.add(params, 'pulseSpeed', 0.3, 10, 0.1);
  fPulse.add(params, 'pulseFrequency', 0, 5, 0.1);
  fPulse.add(params, 'pulseBrightness', 0.1, 2, 0.05);

  const fVis = gui.addFolder('Visuals');
  fVis.addColor(params, 'bgColor').name('background');
  fVis.addColor(params, 'glowColor').name('bg glow');
  fVis.addColor(params, 'branchColor').name('branch');
  fVis.addColor(params, 'accentColor').name('accent branch');
  fVis.addColor(params, 'synapseColor').name('synapse');
  fVis.addColor(params, 'pulseColor').name('pulse');
  fVis.add(params, 'scanlines');

  gui.add(params, 'regenerate').name('>> regenerate network');
  gui.add(params, 'clear').name('>> clear canvas');
  gui.add(params, 'togglePause').name('>> pause / resume');
}

/* =========================================================
   MAIN LOOP
   ========================================================= */
let last = performance.now();

function frame(now) {
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  if (!paused) {
    stepGrowth();
    stepPulses(dt);
  }
  drawScene(now);
  requestAnimationFrame(frame);
}

buildGUI();
regenerate();
requestAnimationFrame(frame);
</script>
</body>
</html>
"}

